function areThirdPartyKeyboardsAllowed() {
    var UIApplication = ObjC.classes.UIApplication.sharedApplication();
    var shouldAllowKeyboardExtension = true;
    var isDelegateImplemented = false;
    try {
        shouldAllowKeyboardExtension = UIApplication.delegate().application_shouldAllowExtensionPointIdentifier_(UIApplication, "com.apple.keyboard-service");
        isDelegateImplemented = true;
        console.log("App delegate implements application:shouldAllowExtensionPointIdentifier:");
    } catch (e) {
        if (e instanceof TypeError) {
            console.log("App delegate has no application:shouldAllowExtensionPointIdentifier:, default behaviour applies:");
        }
    }

    if (shouldAllowKeyboardExtension) {
        console.log("-> Third-party keyboards are allowed.")
    } else {
        console.log("-> Third-party keyboards are NOT allowed.")
    }

    if (shouldAllowKeyboardExtension && isDelegateImplemented) {
        console.log("\nNote: App delegate is implemented but is configured to allow third-party keyboards.");
        console.log("      Review the implementation to check if third-party keyboard support is configurable.");
    }
}

/*
 * iOS Keyboard Cache
 *
 * iterateInputTraits() - Iterate over all UITextView, UITextField (including UISearchBar) elements in the current view and check if keyboard caching is disabled on these text inputs
 *
 */

function resolveAutocorrectionType(typeNr) {
    switch (parseInt(typeNr, 10)) {
        case 1:
            return "UITextAutocorrectionTypeNo"
            break;
        case 2:
            return "UITextAutocorrectionTypeYes"
            break;
        default:
            return "UITextAutocorrectionTypeDefault"
    }
}

function iterateInputTraits() {
    var inputTraits = [ObjC.classes.UITextView, ObjC.classes.UITextField];
    inputTraits.forEach(function(inputTrait) {
        ObjC.choose(inputTrait, {
            onMatch: function(ui) {
                console.log("-".repeat(100));
                console.log(ui);
                console.log("is Editable: ", ui.isEditable());
                console.log("secureTextEntry: ", ui.isSecureTextEntry());
                console.log("autocorrectionType: " + ui.autocorrectionType() + " (" + resolveAutocorrectionType(ui.autocorrectionType()) + ")")
            },
            onComplete: function() {
                console.log("-".repeat(100));
                console.log("Finished searching for " + inputTrait.toString() + " elements.");
            }
        });
    });
}

// deeplink.js - generico para qualquer app iOS
// frida -U -n "Nome do App" -l deeplink.js
//
// No console:
//   o("scheme://host/path?param=valor")
//   history()   -> mostra os deeplinks disparados na sessao
//   last()      -> redispara o ultimo

'use strict';

const _history = [];

function openURL(urlString) {
    if (!ObjC.available) {
        console.log('[!] ObjC indisponivel');
        return;
    }

    ObjC.schedule(ObjC.mainQueue, function() {
        try {
            const url = ObjC.classes.NSURL.URLWithString_(urlString);
            if (!url || url.isNull()) {
                console.log('[!] URL invalida: ' + urlString);
                return;
            }
            const app = ObjC.classes.UIApplication.sharedApplication();
            if (app.respondsToSelector_(ObjC.selector('openURL:options:completionHandler:'))) {
                app.openURL_options_completionHandler_(url, ObjC.classes.NSDictionary.dictionary(), NULL);
            } else {
                app.openURL_(url);
            }
            _history.push(urlString);
            console.log('[+] ' + urlString);
        } catch (e) {
            console.log('[!] Erro: ' + e);
        }
    });
}

globalThis.o = openURL;
globalThis.open = openURL;
globalThis.history = () => _history.forEach((u, i) => console.log(`[${i}] ${u}`));
globalThis.last = () => _history.length ? openURL(_history[_history.length - 1]) : console.log('[!] Historico vazio');

console.log('\n[*] Generico - funciona em qualquer app iOS');
console.log('    o("scheme://...")   -> dispara deeplink');
console.log('    history()           -> lista disparados');
console.log('    last()              -> redispara o ultimo\n');

'use strict';

/* small script to dump UITextField and UITextView attributes for a view
 * (keyWindow by default if invoked with no arg)
 *
 * primarily to see the autocorrectType setting without dumping the whole UI
 */

var UITextAutocorrectionType = ["default", "no", "yes"]

function dumpUIText(view) {
    if (!view) {
        view = ObjC.classes.UIWindow.keyWindow();
    }

    var subviews = view.subviews();
    var count = subviews.count();
    for (var i = 0; i < count; i++) {
        var x = subviews.objectAtIndex_(i);
        if (x.isKindOfClass_(ObjC.classes.UITextField) || x.isKindOfClass_(ObjC.classes.UITextView)) {
            console.log("<" + x.$className + ": " + x.handle + ">");
            console.log("    autocorrectionType: " + UITextAutocorrectionType[x.autocorrectionType()]);
            if (x.text() != "") {
                console.log("    content: " + x.text());
            }
            // this may not always work, i'm making some assumptions about subviews
        } else if (x.isKindOfClass_(ObjC.classes.UITextFieldLabel)) {
            console.log("    Label: " + x.text());
        }
        dumpUIText(x);
    }
}

/*
 *  Convenience functions to access app info.
 *  Dump key app paths and metadata:
 *      appInfo()
 *
 *  Print contents of Info.plist:
 *      infoDictionary()
 *
 *  Query Info.plist by key:
 *      infoLookup("NSAppTransportSecurity")
 *
 */

function dictFromNSDictionary(nsDict) {
    var jsDict = {};
    var keys = nsDict.allKeys();
    var count = keys.count();
    for (var i = 0; i < count; i++) {
        var key = keys.objectAtIndex_(i);
        var value = nsDict.objectForKey_(key);
        jsDict[key.toString()] = value.toString();
    }

    return jsDict;
}

function arrayFromNSArray(nsArray) {
    var jsArray = [];
    var count = nsArray.count();
    for (var i = 0; i < count; i++) {
        jsArray[i] = nsArray.objectAtIndex_(i).toString();
    }
    return jsArray;
}

function infoDictionary() {
    if (ObjC.available && "NSBundle" in ObjC.classes) {
        var info = ObjC.classes.NSBundle.mainBundle().infoDictionary();
        return dictFromNSDictionary(info);
    }
    return null;
}

function infoLookup(key) {
    if (ObjC.available && "NSBundle" in ObjC.classes) {
        var info = ObjC.classes.NSBundle.mainBundle().infoDictionary();
        var value = info.objectForKey_(key);
        if (value === null) {
            return value;
        } else if (value.class().toString() === "__NSCFArray") {
            return arrayFromNSArray(value);
        } else if (value.class().toString() === "__NSCFDictionary") {
            return dictFromNSDictionary(value);
        } else {
            return value.toString();
        }
    }
    return null;
}

function appInfo() {
    var output = {};
    output["Name"] = infoLookup("CFBundleName");
    output["Bundle ID"] = ObjC.classes.NSBundle.mainBundle().bundleIdentifier().toString();
    output["Version"] = infoLookup("CFBundleVersion");
    output["Bundle"] = ObjC.classes.NSBundle.mainBundle().bundlePath().toString();
    output["Data"] = ObjC.classes.NSProcessInfo.processInfo().environment().objectForKey_("HOME").toString();
    output["Binary"] = ObjC.classes.NSBundle.mainBundle().executablePath().toString();
    return output;
}

/* Sample output

