 * Usage: frida -U -n itunesstored --codeshare oleavr/ios-list-apps
 *
 * Then:
 *   list()
 */

'use strict';

var NSAutoreleasePool = ObjC.classes.NSAutoreleasePool;
var NSNumber = ObjC.classes.NSNumber;
var SoftwareLibraryLookupOperation = ObjC.classes.SoftwareLibraryLookupOperation;

function list () {
  var pool = NSAutoreleasePool.alloc().init();
  try {
    var op = SoftwareLibraryLookupOperation.alloc().initWithBundleIdentifiers_(NULL);
    op.autorelease();
    op.run();
    return nsArrayMap(op.softwareLibraryItems(), parseSoftwareLibraryItem);
  } finally {
    pool.release();
  }
}

function parseSoftwareLibraryItem (item) {
  var result = {};
  nsDictionaryForEach(item.$ivars._propertyValues, function (key, value) {
    var parsedValue;
    if (value.isKindOfClass_(NSNumber)) {
      parsedValue = value.doubleValue();
    } else {
      parsedValue = value.toString();
    }
    result[key] = parsedValue;
  });
  return result;
}

function nsArrayMap (array, callback) {
  var result = [];
  var count = array.count().valueOf();
  for (var index = 0; index !== count; index++)
    result.push(callback(array.objectAtIndex_(index)));
  return result;
}

function nsDictionaryForEach (dict, callback) {
  var keys = dict.allKeys();
  var count = keys.count().valueOf();
  for (var i = 0; i !== count; i++) {
    var key = keys.objectAtIndex_(i);
    var value = dict.objectForKey_(key);
    callback(key.toString(), value);
  }
}

/*
 * Inject into PowerUIAgent (SIP must be disabled)
 */

const {
  NSAutoreleasePool,
  PowerUISmartChargeManager,
} = ObjC.classes;

let onComplete;

function forceDesktopMode() {
  withManager(manager => {
    manager.setDesktopMode_withHandler_('DesktopMode', onComplete);
    console.log('Forced desktop mode');
  });
}

function resetDesktopMode() {
  withManager(manager => {
    manager.resetDesktopModeWithHandler_(onComplete);
    console.log('Reset desktop mode');
  });
}

onComplete = new ObjC.Block({
  retType: 'void',
  argTypes: ['int64'],
  implementation(result) {
    console.log(`onComplete() result=${result}`);
  }
});

function enableCharging() {
  withManager(manager => {
    manager.enableCharging();
    console.log('Enabled charging');
  });
}

function disableCharging() {
  withManager(manager => {
    manager.disableCharging();
    console.log('Disabled charging');
  });
}

function withManager(work) {
  const pool = NSAutoreleasePool.alloc().init();
  try {
    const manager = PowerUISmartChargeManager.manager();
    ObjC.schedule(manager.queue(), () => {
      work(manager);
    });
  } finally {
    pool.release();
  }
}

/* Lists all installed apps on iOS
   Example: frida --codeshare sdcampbell/list-ios-apps -U -n SpringBoard
*/

ObjC.schedule(ObjC.mainQueue, function() {
    var workspace = ObjC.classes.LSApplicationWorkspace.defaultWorkspace();
    var apps = workspace.allApplications();
    var appEnumerator = apps.objectEnumerator();
    var app;
    while ((app = appEnumerator.nextObject()) !== null) {
        console.log(app.applicationIdentifier().toString() + ": " + app.localizedName().toString());
    }
});

